package com.cdac.cssip.auth.controller; import com.cdac.cssip.auth.dto.AuthDtos.*; import com.cdac.cssip.auth.entity.ValidId; import com.cdac.cssip.auth.service.AuthService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/auth") @RequiredArgsConstructor public class AuthController{private final AuthService s;@PostMapping("/register")public RegisterResponse register(@Valid @RequestBody RegisterRequest r){return s.register(r);}@PostMapping("/login")public LoginResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);}@PostMapping("/valid-ids")public ValidId add(@RequestHeader("X-Bootstrap-Key")String k,@Valid @RequestBody CreateValidIdRequest r){if(!"cssip-bootstrap".equals(k))throw new SecurityException("Invalid bootstrap key");return s.add(r);}}
